const row = $json;

const text = (value) => {
  if (value == null) return '';
  if (Array.isArray(value)) {
    return value
      .map((item) => String(item ?? '').trim())
      .filter(Boolean)
      .join(' ');
  }
  return String(value).trim();
};

const upper = (value) => text(value).toUpperCase();
const lower = (value) => text(value).toLowerCase();

const normalizeTitle = (value) =>
  text(value)
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[â€”â€“_-]+/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const uuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const random = Math.floor(Math.random() * 16);
    return (
      character === 'x'
        ? random
        : ((random & 3) | 8)
    ).toString(16);
  });

const status = lower(row['Processing Status']);
const operation = text(row['Operation']);
const formResponseId = text(row['Form Response ID']);
const retryCountValue = Number(row['Retry Count'] || 0);

const queue = {
  formResponseId,
  retryCount: Number.isFinite(retryCountValue) ? retryCountValue : 0,
  incomingStatus: status,
  operation,
};

const processable =
  status === 'pending' &&
  operation === 'marks.batch.submit';

if (!processable) {
  return {
    json: {
      processable: false,
      queue,
      skipReason:
        status !== 'pending'
          ? 'QUEUE_ROW_NOT_PENDING'
          : 'QUEUE_OPERATION_MISMATCH',
    },
  };
}

if (!formResponseId) {
  throw new Error('VALIDATION_FORM_RESPONSE_ID_REQUIRED');
}

let raw = row['Raw Response JSON'];

if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch {
    throw new Error('VALIDATION_RAW_RESPONSE_JSON');
  }
}

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  throw new Error('VALIDATION_RAW_RESPONSE_OBJECT');
}

const rawEntries = Object.entries(raw);

const findFormValue = ({
  aliases = [],
  requiredWords = [],
  preferredWords = [],
  valueValidator = null,
}) => {
  const normalizedAliases = aliases.map(normalizeTitle);

  for (const [key, value] of rawEntries) {
    if (normalizedAliases.includes(normalizeTitle(key))) {
      return text(value);
    }
  }

  for (const [key, value] of rawEntries) {
    const normalizedKey = normalizeTitle(key);
    const hasRequiredWords = requiredWords.every((word) =>
      normalizedKey.includes(normalizeTitle(word))
    );
    const hasPreferredWord =
      preferredWords.length === 0 ||
      preferredWords.some((word) =>
        normalizedKey.includes(normalizeTitle(word))
      );
    const validValue =
      typeof valueValidator !== 'function' ||
      valueValidator(value);

    if (hasRequiredWords && hasPreferredWord && validValue) {
      return text(value);
    }
  }

  return '';
};

const declarationText = findFormValue({
  aliases: [
    'I confirm that I am assigned to this class and that these marks are accurate.',
    'Teacher confirmation',
    'Confirmation',
  ],
  requiredWords: ['confirm'],
  preferredWords: ['assigned', 'class', 'marks', 'accurate'],
});

if (!lower(declarationText).includes('confirm')) {
  throw new Error('VALIDATION_TEACHER_DECLARATION_REQUIRED');
}

const marksText = findFormValue({
  aliases: [
    'Marks â€” one line per student: student_number,marks,absent,remarks',
    'Marks - one line per student: student_number,marks,absent,remarks',
    'Marks Ã¢â‚¬â€ one line per student: student_number,marks,absent,remarks',
    'Enter marks',
    'Student marks',
  ],
  requiredWords: ['marks'],
  preferredWords: ['student', 'remarks', 'absent'],
  valueValidator: (value) => {
    const candidate = text(value);
    return (
      candidate.includes(',') &&
      (candidate.includes('\n') || /^[A-Za-z0-9-]+\s*,/.test(candidate))
    );
  },
});

const lines = marksText
  .split(/\r?\n/)
  .map((line) => line.trim())
  .filter(Boolean);

if (lines.length === 0) {
  throw new Error('VALIDATION_MARKS_LINES_REQUIRED');
}

const absentTokens = new Set(['true', 'yes', 'y', 'absent', 'a']);
const missingTokens = new Set(['missing', 'm']);
const presentTokens = new Set(['', 'false', 'no', 'n', 'present', 'p']);

const marks = lines.map((line, index) => {
  const lineNumber = index + 1;
  const parts = line.split(',');

  if (parts.length < 3) {
    throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_FORMAT`);
  }

  const studentNumber = upper(parts.shift());
  const marksValue = text(parts.shift());
  const stateToken = lower(parts.shift());
  const remarks = text(parts.join(','));

  if (!studentNumber) {
    throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_STUDENT`);
  }

  let marksObtained = null;
  let isAbsent = false;
  let isMissing = false;

  if (absentTokens.has(stateToken)) {
    if (marksValue !== '') {
      throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_ABSENT_VALUE`);
    }
    isAbsent = true;
  } else if (missingTokens.has(stateToken)) {
    if (marksValue !== '') {
      throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_MISSING_VALUE`);
    }
    isMissing = true;
  } else if (presentTokens.has(stateToken)) {
    if (marksValue === '') {
      throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_MARKS_REQUIRED`);
    }

    const parsedMarks = Number(marksValue);
    if (!Number.isFinite(parsedMarks) || parsedMarks < 0) {
      throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_MARKS_INVALID`);
    }
    marksObtained = parsedMarks;
  } else {
    throw new Error(`VALIDATION_MARKS_LINE_${lineNumber}_STATE`);
  }

  return {
    student_number: studentNumber,
    marks_obtained: marksObtained,
    is_absent: isAbsent,
    is_missing: isMissing,
    remarks: remarks || null,
  };
});

const studentNumbers = marks.map((mark) => mark.student_number);
if (new Set(studentNumbers).size !== studentNumbers.length) {
  throw new Error('VALIDATION_DUPLICATE_STUDENT_NUMBER');
}

const getByAliases = (aliases, requiredWords = [], preferredWords = []) =>
  findFormValue({ aliases, requiredWords, preferredWords });

const submissionStateRaw = lower(
  getByAliases(
    ['Submission state', 'Submission status', 'Draft or finalize'],
    ['submission'],
    ['state', 'status', 'draft', 'finalize']
  )
);

const submissionState =
  submissionStateRaw.includes('finalize')
    ? 'finalize'
    : 'draft';

const correlationId = uuid();
const idempotencyKey =
  text(row['Idempotency Key']) ||
  `google-form:${text(row['Source Form ID'])}:${formResponseId}`;
const teacherEmail = lower(row['Respondent Email']);

if (!teacherEmail) {
  throw new Error('AUTH_CAPTURED_TEACHER_EMAIL_REQUIRED');
}

const request = {
  operation: 'marks.batch.submit',
  correlation_id: correlationId,
  idempotency_key: idempotencyKey,
  requester: {
    email: teacherEmail,
    type: 'authorized_teacher_google_form',
  },
  submitted_at:
    text(row['Submitted At UTC']) ||
    new Date().toISOString(),
  source: {
    channel: 'google_forms',
    source_submission_id: formResponseId,
    source_form_id: text(row['Source Form ID']),
    source_spreadsheet_id: text(row['Source Spreadsheet ID']),
  },
  payload: {
    institution_code: upper(
      getByAliases(['Institution code'], ['institution', 'code'])
    ),
    campus_code: upper(
      getByAliases(['Campus code'], ['campus', 'code'])
    ),
    term_code: upper(
      getByAliases(
        ['Term or semester code', 'Term code', 'Semester code'],
        ['code'],
        ['term', 'semester']
      )
    ),
    course_offering_code: upper(
      getByAliases(
        ['Course offering code', 'Offering code'],
        ['offering', 'code']
      )
    ),
    section_code: upper(
      getByAliases(['Section code'], ['section', 'code'])
    ),
    assessment_code: upper(
      getByAliases(['Assessment code'], ['assessment', 'code'])
    ),
    submission_state: submissionState,
    teacher_email: teacherEmail,
    teacher_notes: getByAliases(
      ['Teacher notes', 'Submission notes', 'Notes'],
      ['notes']
    ),
    marks,
  },
};

for (const [key, value] of Object.entries({
  institution_code: request.payload.institution_code,
  campus_code: request.payload.campus_code,
  term_code: request.payload.term_code,
  course_offering_code: request.payload.course_offering_code,
  section_code: request.payload.section_code,
  assessment_code: request.payload.assessment_code,
})) {
  if (!value) {
    throw new Error(`VALIDATION_${key.toUpperCase()}_REQUIRED`);
  }
}

return {
  json: {
    processable: true,
    queue,
    request,
    markCount: marks.length,
  },
};

const source = $('Normalize Manual Marks Queue Row').item.json;
const raw = $json ?? {};

let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = { message: body };
  }
}

if (
  Array.isArray(body) &&
  body.length === 1 &&
  body[0] &&
  typeof body[0] === 'object'
) {
  body = body[0];
}

const statusValue = raw.statusCode ?? raw.status ?? null;
const statusCode =
  statusValue == null
    ? (raw.error ? 0 : 200)
    : Number(statusValue);

const transportError =
  typeof raw.error === 'string'
    ? raw.error
    : (raw.error?.message || raw.message || '');

const bodyError =
  body && typeof body === 'object'
    ? (
        body.error && typeof body.error === 'object'
          ? body.error
          : body
      )
    : {};

const rpcSuccess =
  statusCode >= 200 &&
  statusCode < 300 &&
  body &&
  typeof body === 'object' &&
  body.success === true;

const errorCode = rpcSuccess
  ? ''
  : String(
      bodyError.code ||
      bodyError.error_code ||
      (statusCode > 0 ? `HTTP_${statusCode}` : 'NETWORK_FAILURE')
    ).slice(0, 100);

const errorMessage = rpcSuccess
  ? ''
  : String(
      bodyError.message ||
      bodyError.error_message ||
      transportError ||
      'The marks operation could not be completed.'
    ).slice(0, 300);

const now = new Date().toISOString();

return {
  json: {
    'Form Response ID': source.queue.formResponseId,
    'Processing Status': rpcSuccess ? 'completed' : 'failed',
    'Processed At UTC': now,
    'Correlation ID':
      body?.correlation_id || source.request.correlation_id,
    'Error Code': errorCode,
    'Error Message': errorMessage,
    'Retry Count':
      source.queue.retryCount + (rpcSuccess ? 0 : 1),
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    marksBatchId: body?.data?.marks_batch_id || '',
    batchStatus: body?.data?.status || '',
    validationSummary: body?.data?.validation_summary || {},
    rpcResult: body,
    httpStatusCode: statusCode,
    success: rpcSuccess,
  },
};

const row = $json;
const text = (value) => value == null ? '' : String(value).trim();
const lower = (value) => text(value).toLowerCase();
const upper = (value) => text(value).toUpperCase();

const normalizeTitle = (value) =>
  text(value)
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[â€”â€“_-]+/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const uuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const random = Math.floor(Math.random() * 16);
    return (
      character === 'x'
        ? random
        : ((random & 3) | 8)
    ).toString(16);
  });

const status = lower(row['Processing Status']);
const operation = text(row['Operation']);
const formResponseId = text(row['Form Response ID']);
const retryCountValue = Number(row['Retry Count'] || 0);

const queue = {
  formResponseId,
  retryCount: Number.isFinite(retryCountValue) ? retryCountValue : 0,
  incomingStatus: status,
  operation,
};

const processable =
  status === 'pending' &&
  operation === 'marks.file.submit';

if (!processable) {
  return {
    json: {
      processable: false,
      queue,
      skipReason:
        status !== 'pending'
          ? 'QUEUE_ROW_NOT_PENDING'
          : 'QUEUE_OPERATION_MISMATCH',
    },
  };
}

if (!formResponseId) {
  throw new Error('VALIDATION_FORM_RESPONSE_ID_REQUIRED');
}

let raw = row['Raw Response JSON'];
if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch {
    throw new Error('VALIDATION_RAW_RESPONSE_JSON');
  }
}

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  throw new Error('VALIDATION_RAW_RESPONSE_OBJECT');
}

const entries = Object.entries(raw);
const find = (aliases, requiredWords = []) => {
  const normalizedAliases = aliases.map(normalizeTitle);

  for (const [key, value] of entries) {
    if (normalizedAliases.includes(normalizeTitle(key))) {
      return text(value);
    }
  }

  for (const [key, value] of entries) {
    const normalizedKey = normalizeTitle(key);
    if (
      requiredWords.every((word) =>
        normalizedKey.includes(normalizeTitle(word))
      )
    ) {
      return text(value);
    }
  }

  return '';
};

const declaration = find(
  [
    'I confirm that I am authorized to submit this class file.',
    'Authorization confirmation',
  ],
  ['confirm', 'authorized']
);

if (!lower(declaration).includes('confirm')) {
  throw new Error('VALIDATION_FILE_DECLARATION_REQUIRED');
}

const driveUrl = find(
  ['Uploaded CSV or Excel Google Drive URL', 'Google Drive URL', 'Drive URL'],
  ['drive', 'url']
);

const originalFileName = find(
  ['Original file name', 'File name'],
  ['file', 'name']
);

const extractDriveFileId = (value) => {
  const candidate = text(value);

  const patterns = [
    /\/d\/([A-Za-z0-9_-]{10,})/i,
    /[?&]id=([A-Za-z0-9_-]{10,})/i,
    /^([A-Za-z0-9_-]{10,})$/,
  ];

  for (const pattern of patterns) {
    const match = candidate.match(pattern);
    if (match) return match[1];
  }

  return '';
};

const fileId = extractDriveFileId(driveUrl);
if (!fileId) {
  throw new Error('VALIDATION_GOOGLE_DRIVE_FILE_ID');
}

const extensionMatch = lower(originalFileName).match(/\.([a-z0-9]+)$/);
const fileExtension = extensionMatch ? extensionMatch[1] : '';

if (!['csv', 'xlsx', 'xls'].includes(fileExtension)) {
  throw new Error('VALIDATION_MARKS_FILE_TYPE');
}

const teacherEmail = lower(row['Respondent Email']);
if (!teacherEmail) {
  throw new Error('AUTH_CAPTURED_TEACHER_EMAIL_REQUIRED');
}

const submissionStateRaw = lower(
  find(['Submission state', 'Submission status'], ['submission'])
);
const submissionState =
  submissionStateRaw.includes('finalize')
    ? 'finalize'
    : 'draft';

const correlationId = uuid();
const idempotencyKey =
  text(row['Idempotency Key']) ||
  `google-form:${text(row['Source Form ID'])}:${formResponseId}`;

const formContext = {
  institutionCode: upper(find(['Institution code'], ['institution', 'code'])),
  campusCode: upper(find(['Campus code'], ['campus', 'code'])),
  termCode: upper(
    find(['Term or semester code', 'Term code', 'Semester code'], ['code'])
  ),
  courseOfferingCode: upper(
    find(['Course offering code', 'Offering code'], ['offering', 'code'])
  ),
  sectionCode: upper(find(['Section code'], ['section', 'code'])),
  assessmentCode: upper(find(['Assessment code'], ['assessment', 'code'])),
  submissionState,
  teacherEmail,
  teacherNotes: find(['File notes', 'Teacher notes', 'Notes'], ['notes']),
};

for (const [key, value] of Object.entries(formContext)) {
  if (
    [
      'institutionCode',
      'campusCode',
      'termCode',
      'courseOfferingCode',
      'sectionCode',
      'assessmentCode',
      'teacherEmail',
    ].includes(key) &&
    !value
  ) {
    throw new Error(`VALIDATION_${key.replace(/([a-z])([A-Z])/g, '$1_$2').toUpperCase()}_REQUIRED`);
  }
}

return {
  json: {
    processable: true,
    queue,
    correlationId,
    idempotencyKey,
    submittedAt:
      text(row['Submitted At UTC']) ||
      new Date().toISOString(),
    sourceFormId: text(row['Source Form ID']),
    sourceSpreadsheetId: text(row['Source Spreadsheet ID']),
    driveUrl,
    fileId,
    originalFileName,
    fileExtension,
    formContext,
  },
};

const source = $('Normalize Marks File Queue Row').item.json;
const binary = $binary?.data;
const now = new Date().toISOString();

if (!binary) {
  const errorText = String(
    $json?.error?.message ||
    $json?.error ||
    $json?.message ||
    'Google Drive did not return a binary file.'
  );

  return {
    json: {
      ...source,
      downloadReady: false,
      'Form Response ID': source.queue.formResponseId,
      'Processing Status': 'failed',
      'Processed At UTC': now,
      'Correlation ID': source.correlationId,
      'Error Code': 'FILE_DOWNLOAD_FAILED',
      'Error Message': errorText.slice(0, 300),
      'Retry Count': source.queue.retryCount + 1,
      'Last Attempt At UTC': now,
      'n8n Execution ID': $execution.id,
      success: false,
    },
  };
}

const actualExtension = String(binary.fileExtension || '')
  .toLowerCase()
  .replace(/^\./, '');

if (
  actualExtension &&
  !['csv', 'xlsx', 'xls'].includes(actualExtension)
) {
  return {
    json: {
      ...source,
      downloadReady: false,
      'Form Response ID': source.queue.formResponseId,
      'Processing Status': 'failed',
      'Processed At UTC': now,
      'Correlation ID': source.correlationId,
      'Error Code': 'FILE_TYPE_UNSUPPORTED',
      'Error Message':
        `Downloaded file type "${actualExtension}" is not CSV, XLSX or XLS.`,
      'Retry Count': source.queue.retryCount + 1,
      'Last Attempt At UTC': now,
      'n8n Execution ID': $execution.id,
      success: false,
    },
  };
}

if (
  actualExtension &&
  actualExtension !== source.fileExtension
) {
  return {
    json: {
      ...source,
      downloadReady: false,
      'Form Response ID': source.queue.formResponseId,
      'Processing Status': 'failed',
      'Processed At UTC': now,
      'Correlation ID': source.correlationId,
      'Error Code': 'FILE_EXTENSION_MISMATCH',
      'Error Message':
        `Declared extension "${source.fileExtension}" does not match downloaded extension "${actualExtension}".`,
      'Retry Count': source.queue.retryCount + 1,
      'Last Attempt At UTC': now,
      'n8n Execution ID': $execution.id,
      success: false,
    },
  };
}

return {
  json: {
    ...source,
    downloadReady: true,
    downloadedMimeType: binary.mimeType || '',
    downloadedFileName: binary.fileName || source.originalFileName,
  },
  binary: $binary,
};

const source = $('Normalize Marks File Queue Row').first().json;
const inputItems = $input.all();
const now = new Date().toISOString();

const failure = (errorCode, errorMessage, incrementRetry = false) => [
  {
    json: {
      ...source,
      requestReady: false,
      'Form Response ID': source.queue.formResponseId,
      'Processing Status': 'failed',
      'Processed At UTC': now,
      'Correlation ID': source.correlationId,
      'Error Code': String(errorCode || 'FILE_VALIDATION_FAILED')
        .trim()
        .toUpperCase()
        .replace(/[^A-Z0-9_]+/g, '_')
        .slice(0, 100),
      'Error Message': String(
        errorMessage || 'The uploaded marks file did not pass validation.'
      ).slice(0, 300),
      'Retry Count':
        source.queue.retryCount + (incrementRetry ? 1 : 0),
      'Last Attempt At UTC': now,
      'n8n Execution ID': $execution.id,
      success: false,
    },
  },
];

if (inputItems.length === 0) {
  return failure(
    'FILE_EMPTY',
    'The uploaded marks file contains no data rows.'
  );
}

const extractionError = inputItems.find(
  (item) =>
    item.json?.error ||
    item.json?.errorMessage ||
    Number(item.json?.statusCode || item.json?.status || 0) >= 400
);

if (extractionError) {
  const extractionMessage =
    extractionError.json?.error?.message ||
    extractionError.json?.errorMessage ||
    extractionError.json?.error ||
    extractionError.json?.message ||
    'The uploaded marks file could not be parsed.';

  return failure(
    'FILE_PARSE_FAILED',
    extractionMessage,
    false
  );
}

const normalizeHeader = (value) =>
  String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const truthy = new Set([
  'true',
  'yes',
  'y',
  '1',
  'absent',
  'missing',
]);

const falsy = new Set([
  '',
  'false',
  'no',
  'n',
  '0',
  'present',
]);

const getColumn = (row, aliases) => {
  const mapped = {};

  for (const [key, value] of Object.entries(row || {})) {
    mapped[normalizeHeader(key)] = value;
  }

  for (const alias of aliases) {
    const normalizedAlias = normalizeHeader(alias);

    if (
      Object.prototype.hasOwnProperty.call(
        mapped,
        normalizedAlias
      )
    ) {
      return mapped[normalizedAlias];
    }
  }

  return undefined;
};

try {
  const marks = inputItems.map((item, index) => {
    const row = item.json || {};
    const line = index + 2;

    const studentNumber = String(
      getColumn(row, [
        'student_number',
        'student number',
        'student_id',
        'student id',
      ]) ?? ''
    )
      .trim()
      .toUpperCase();

    if (!studentNumber) {
      throw new Error(
        `FILE_ROW_${line}_STUDENT_NUMBER_REQUIRED`
      );
    }

    const absentValue = String(
      getColumn(row, ['absent', 'is_absent']) ?? ''
    )
      .trim()
      .toLowerCase();

    const missingValue = String(
      getColumn(row, ['missing', 'is_missing']) ?? ''
    )
      .trim()
      .toLowerCase();

    if (
      !truthy.has(absentValue) &&
      !falsy.has(absentValue)
    ) {
      throw new Error(
        `FILE_ROW_${line}_ABSENT_INVALID`
      );
    }

    if (
      !truthy.has(missingValue) &&
      !falsy.has(missingValue)
    ) {
      throw new Error(
        `FILE_ROW_${line}_MISSING_INVALID`
      );
    }

    const isAbsent = truthy.has(absentValue);
    const isMissing = truthy.has(missingValue);

    if (isAbsent && isMissing) {
      throw new Error(
        `FILE_ROW_${line}_ABSENT_AND_MISSING`
      );
    }

    const marksRaw = getColumn(row, [
      'marks',
      'marks_obtained',
      'obtained_marks',
      'score',
    ]);

    let marksObtained = null;

    if (!isAbsent && !isMissing) {
      const marksText = String(marksRaw ?? '').trim();

      if (marksText === '') {
        throw new Error(
          `FILE_ROW_${line}_MARKS_REQUIRED`
        );
      }

      const parsedMarks = Number(marksText);

      if (
        !Number.isFinite(parsedMarks) ||
        parsedMarks < 0
      ) {
        throw new Error(
          `FILE_ROW_${line}_MARKS_INVALID`
        );
      }

      marksObtained = parsedMarks;
    } else if (String(marksRaw ?? '').trim() !== '') {
      throw new Error(
        `FILE_ROW_${line}_NON_PRESENT_MARKS_VALUE`
      );
    }

    return {
      student_number: studentNumber,
      marks_obtained: marksObtained,
      is_absent: isAbsent,
      is_missing: isMissing,
      remarks:
        String(
          getColumn(row, [
            'remarks',
            'comment',
            'comments',
            'notes',
          ]) ?? ''
        ).trim() || null,
    };
  });

  const studentNumbers = marks.map(
    (mark) => mark.student_number
  );

  const duplicateStudentNumbers = [
    ...new Set(
      studentNumbers.filter(
        (studentNumber, index) =>
          studentNumbers.indexOf(studentNumber) !== index
      )
    ),
  ];

  if (duplicateStudentNumbers.length > 0) {
    return failure(
      'VALIDATION_DUPLICATE_STUDENT_NUMBER',
      `Duplicate student number detected: ${duplicateStudentNumbers.join(', ')}.`
    );
  }

  const context = source.formContext;

  return [
    {
      json: {
        ...source,
        requestReady: true,
        markCount: marks.length,
        request: {
          operation: 'marks.batch.submit',
          correlation_id: source.correlationId,
          idempotency_key: source.idempotencyKey,
          requester: {
            email: context.teacherEmail,
            type:
              'authorized_teacher_google_form_file_upload',
          },
          submitted_at: source.submittedAt,
          source: {
            channel: 'google_forms_drive_upload',
            source_submission_id:
              source.queue.formResponseId,
            source_form_id: source.sourceFormId,
            source_spreadsheet_id:
              source.sourceSpreadsheetId,
            source_file_id: source.fileId,
            source_file_name: source.originalFileName,
          },
          payload: {
            institution_code:
              context.institutionCode,
            campus_code: context.campusCode,
            term_code: context.termCode,
            course_offering_code:
              context.courseOfferingCode,
            section_code: context.sectionCode,
            assessment_code:
              context.assessmentCode,
            submission_state:
              context.submissionState,
            teacher_email: context.teacherEmail,
            teacher_notes: context.teacherNotes,
            marks,
          },
        },
      },
    },
  ];
} catch (error) {
  const code =
    error instanceof Error && error.message
      ? error.message
      : 'FILE_VALIDATION_FAILED';

  return failure(
    code,
    code.startsWith('FILE_ROW_')
      ? `The uploaded marks file contains an invalid value (${code}).`
      : 'The uploaded marks file did not pass validation.'
  );
}

const source = $('Build File Marks Request').item.json;
const raw = $json ?? {};

let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = { message: body };
  }
}

if (
  Array.isArray(body) &&
  body.length === 1 &&
  body[0] &&
  typeof body[0] === 'object'
) {
  body = body[0];
}

const statusValue = raw.statusCode ?? raw.status ?? null;
const statusCode =
  statusValue == null
    ? (raw.error ? 0 : 200)
    : Number(statusValue);

const transportError =
  typeof raw.error === 'string'
    ? raw.error
    : (raw.error?.message || raw.message || '');

const bodyError =
  body && typeof body === 'object'
    ? (
        body.error && typeof body.error === 'object'
          ? body.error
          : body
      )
    : {};

const rpcSuccess =
  statusCode >= 200 &&
  statusCode < 300 &&
  body &&
  typeof body === 'object' &&
  body.success === true;

const now = new Date().toISOString();

return {
  json: {
    ...source,
    'Form Response ID': source.queue.formResponseId,
    'Processing Status': rpcSuccess ? 'completed' : 'failed',
    'Processed At UTC': now,
    'Correlation ID':
      body?.correlation_id || source.correlationId,
    'Error Code': rpcSuccess
      ? ''
      : String(
          bodyError.code ||
          bodyError.error_code ||
          (statusCode > 0 ? `HTTP_${statusCode}` : 'NETWORK_FAILURE')
        ).slice(0, 100),
    'Error Message': rpcSuccess
      ? ''
      : String(
          bodyError.message ||
          bodyError.error_message ||
          transportError ||
          'The uploaded marks file could not be submitted.'
        ).slice(0, 300),
    'Retry Count':
      source.queue.retryCount + (rpcSuccess ? 0 : 1),
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    marksBatchId: body?.data?.marks_batch_id || '',
    batchStatus: body?.data?.status || '',
    validationSummary: body?.data?.validation_summary || {},
    rpcResult: body,
    success: rpcSuccess,
  },
};
